#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#define LL long longusing namespace std;LL p, num;LL fastpow(int k) &#123;    if (k == 0) return 1 % p;    if (k == 1) return num % p;    LL re = fastpow(k &gt;&gt; 1);    re = (re * re) % p;    if (k &amp; 1) re = (re * num) % p;    return re;&#125;int main() &#123;    int k;    scanf(&quot;%lld%d%lld&quot;, &amp;num, &amp;k, &amp;p);    printf(&quot;%lld^%d mod %lld=%lld&quot;, num, k, p, fastpow(k));    return 0;&#125;
