#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#define MAXN (10000)#define swap(x, y) &#123; int t = x; x = y; y = t; &#125;using namespace std;struct node &#123;    int fa, size;&#125; a[MAXN + 5];int find(int x) &#123; return ((a[x].fa == x) ? x : (a[x].fa = find(a[x].fa))); &#125;void merge(int x, int y) &#123;    x = find(x), y = find(y);    if (a[x].size &lt; a[y].size) swap(x, y);    a[y].fa = x, a[x].size += a[y].size;&#125;int main() &#123;    int n, m;    scanf(&quot;%d%d&quot;, &amp;n, &amp;m);    for (int i = 1; i &lt;= n; i++)        a[i].fa = i, a[i].size = 1;    for (int i = 1, x, y, z; i &lt;= m; i++) &#123;        scanf(&quot;%d%d%d&quot;, &amp;z, &amp;x, &amp;y);        if (z &amp; 1) merge(x, y);        else puts(find(x) == find(y) ? &quot;Y&quot; : &quot;N&quot;);    &#125;    return 0;&#125;
