#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#define INF (2147483647)#define MAXN (10000)#define MAXM (500000)#define pii pair&lt;int, int&gt;using namespace std;struct edge &#123;    int x, y, cost, next;&#125; e[MAXM + 5];int n, m, g[MAXN + 5], cnte, dis[MAXN + 5], s;bool vis[MAXN + 5];void adde(int x, int y, int c) &#123;    ++cnte;    e[cnte].x = x, e[cnte].y = y, e[cnte].cost = c, e[cnte].next = g[x];    g[x] = cnte;&#125;void dijk() &#123;    dis[s] = 0;    priority_queue&lt;pii, vector&lt;pii&gt;, greater&lt;pii&gt; &gt; q;    q.push(make_pair(0, s));    while (!q.empty()) &#123;        int nown = q.top().second;        q.pop();        if (vis[nown]) continue;        vis[nown] = true;        for (int i = g[nown]; i; i = e[i].next)            if (dis[e[i].y] &gt; dis[nown] + e[i].cost)                q.push(make_pair(dis[e[i].y] = dis[nown] + e[i].cost, e[i].y));    &#125;&#125;int main() &#123;    scanf(&quot;%d%d%d&quot;, &amp;n, &amp;m, &amp;s);    for (int i = 1; i &lt;= n; i++) dis[i] = INF;    memset(vis, false, sizeof(vis));    for (int i = 1, x, y, c; i &lt;= m; i++) &#123;        scanf(&quot;%d%d%d&quot;, &amp;x, &amp;y, &amp;c);        adde(x, y, c);    &#125;    dijk();    for (int i = 1; i &lt;= n; i++)        printf(&quot;%d &quot;, dis[i]);    return 0;&#125;
