#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#define LL long long #define MAXN (100000000)#define MAXP (100000)using namespace std;bool isp[MAXN + 5];int prim[MAXP + 5];int main() &#123;    int n, q;    scanf(&quot;%d%d&quot;, &amp;n, &amp;q);    memset(isp, true, sizeof(isp));    isp[1] = false;    for (int i = 1; i &lt;= n; i++) &#123;        if (isp[i])            prim[++prim[0]] = i;        for (int j = 1; j &lt;= prim[0] &amp;&amp; (LL)i * prim[j] &lt;= n; j++) &#123;            isp[i * prim[j]] = false;            if (i % prim[j] == 0) break;         &#125;    &#125;    for (int i = 1, k; i &lt;= q; i++) &#123;        scanf(&quot;%d&quot;, &amp;k);        printf(&quot;%d\n&quot;, prim[k]);    &#125;    return 0;&#125;
