#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#define MAXN (5000)#define MAXM (200000)using namespace std;struct edge &#123;    int from, to, cost;&#125; b[MAXM + 5];struct node &#123;    int size, fa;&#125; a[MAXN + 5];int find(int x) &#123; return (a[x].fa == x) ? x : (a[x].fa = find(a[x].fa)); &#125;void merge(int x, int y) &#123;    int fx = find(x), fy = find(y);    if (a[fx].size &gt; a[fy].size)        a[fx].size += a[fy].size, a[fy].fa = fx;    else        a[fy].size += a[fx].size, a[fx].fa = fy;&#125;bool cmp(edge&amp; x, edge&amp; y) &#123; return x.cost &lt; y.cost; &#125;int n, m, ans;int main() &#123;    scanf(&quot;%d%d&quot;, &amp;n, &amp;m);    for (int i = 1; i &lt;= n; i++) a[i].fa = i, a[i].size = 1;    for (int i = 1; i &lt;= m; i++) scanf(&quot;%d%d%d&quot;, &amp;b[i].from, &amp;b[i].to, &amp;b[i].cost);    sort(b + 1, b + m + 1, cmp);    for (int i = 1, cnte = 0; i &lt;= m; i++)        if (find(b[i].from) != find(b[i].to)) &#123;            ans += b[i].cost, ++cnte;            merge(b[i].from, b[i].to);            if (cnte == n - 1) break;        &#125;    if (a[find(1)].size != n) puts(&quot;orz&quot;);    else printf(&quot;%d&quot;, ans);    return 0;&#125;
