#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#define MAXN (1000000)#define INF (0x7fffffff)#define pii pair&lt;int, int&gt;using namespace std;int n, k, a[MAXN + 5], head1, tail1, head2, tail2;pii q1[MAXN + 5], q2[MAXN + 5], ans[MAXN + 5];void push(pii x) &#123;    while (tail1 &gt;= head1 &amp;&amp; x.first &lt; q1[tail1].first)        --tail1;    q1[++tail1] = x;    while (tail2 &gt;= head2 &amp;&amp; x.first &gt; q2[tail2].first)        --tail2;    q2[++tail2] = x;&#125;void query(int x) &#123;    while (q1[head1].second &lt;= x - k) ++head1;    while (q2[head2].second &lt;= x - k) ++head2;    ans[x] = make_pair(q1[head1].first, q2[head2].first);&#125;int main() &#123;    scanf(&quot;%d%d&quot;, &amp;n, &amp;k);    for (int i = 1; i &lt;= n; i++) scanf(&quot;%d&quot;, &amp;a[i]);    for (int i = 1; i &lt;= n; i++) push(make_pair(a[i], i)), query(i);    for (int i = k; i &lt;= n; i++) printf(&quot;%d &quot;, ans[i].first);    puts(&quot;&quot;);    for (int i = k; i &lt;= n; i++) printf(&quot;%d &quot;, ans[i].second);    return 0;&#125;
