#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#define MAXN (500000)using namespace std;struct node &#123;    int fa, top, size, hs, deep;&#125; a[MAXN + 5];struct edg &#123;    int from, to, next;&#125; b[(MAXN &lt;&lt; 1) + 5];int root, n, g[MAXN + 5], cntb, q;void ade(int fr, int t) &#123;    b[++cntb] = &#123;fr, t, g[fr]&#125;;    g[fr] = cntb;&#125;void init(int now) &#123;    a[now].size = 1, a[now].deep = a[a[now].fa].deep + 1;    for (int i = g[now]; i; i = b[i].next)        if (b[i].to != a[now].fa) &#123;            a[b[i].to].fa = now;            init(b[i].to);            if (a[b[i].to].size &gt; a[a[now].hs].size) a[now].hs = b[i].to;            a[now].size += a[b[i].to].size;        &#125;&#125;void dfs(int now) &#123;    if (a[now].hs) a[a[now].hs].top = a[now].top, dfs(a[now].hs);    for (int i = g[now]; i; i = b[i].next)        if (b[i].to != a[now].fa &amp;&amp; b[i].to != a[now].hs)            a[b[i].to].top = b[i].to, dfs(b[i].to);&#125;int lca(int x, int y) &#123;    while (a[x].top != a[y].top) &#123;        if (a[a[x].top].deep &lt; a[a[y].top].deep) swap(x, y);        x = a[a[x].top].fa;    &#125;    if (a[x].deep &gt; a[y].deep) swap(x, y);    return x;&#125;int main() &#123;    scanf(&quot;%d%d%d&quot;, &amp;n, &amp;q, &amp;root);    for (int i = 1, x, y; i &lt; n; i++) &#123;        scanf(&quot;%d%d&quot;, &amp;x, &amp;y);        ade(x, y), ade(y, x);    &#125;    a[root].top = a[root].fa = root;    init(root), dfs(root);    for (int i = 1, x, y; i &lt;= q; i++) &#123;        scanf(&quot;%d%d&quot;, &amp;x, &amp;y);        printf(&quot;%d\n&quot;, lca(x, y));    &#125;    return 0;&#125;
最小费用最大流
妈的这比dinic不知道好写到哪里去了
好像常数略大 不开氧气过不去很蛋疼
#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#define MAXN (5000)#define MAXM (50000)#define INF (0x7fffffff)#define rev(i) ((((i) - 1) ^ 1) + 1)using namespace std;struct edg &#123;    int from, to, cost, flow, cap, next;&#125; b[(MAXM &lt;&lt; 1) + 5];int g[MAXN + 5], cntb, n, m, pre[MAXN], s, t, ansf, ansc;void ade(int fr, int t, int ca, int co) &#123;    b[++cntb] = &#123;fr, t, co, 0, ca, g[fr]&#125;;    g[fr] = cntb;&#125;int spfa() &#123;    queue&lt;int&gt; q;    int dis[MAXN + 5], a[MAXN + 5];    bool inq[MAXN + 5];    memset(dis, 0x7f, sizeof(dis));    memset(inq, false, sizeof(inq));    memset(a, 0, sizeof(a));    a[s] = INF, dis[s] = 0;    q.push(s);    while (!q.empty()) &#123;        int now = q.front();        q.pop();        inq[now] = false;        for (int i = g[now]; i; i = b[i].next)            if (b[i].flow &lt; b[i].cap &amp;&amp; dis[b[i].to] &gt; dis[now] + b[i].cost) &#123;                dis[b[i].to] = dis[now] + b[i].cost;                pre[b[i].to] = i;                a[b[i].to] = min(a[now], b[i].cap - b[i].flow);                if (!inq[b[i].to]) inq[b[i].to] = true, q.push(b[i].to);            &#125;    &#125;    return a[t];&#125;void solve() &#123;    int nans;    while (nans = spfa()) &#123;        ansf += nans;        for (int i = t; i != s; i = b[pre[i]].from)            b[pre[i]].flow += nans, b[rev(pre[i])].flow -= nans, ansc += nans * b[pre[i]].cost;    &#125;&#125;int main() &#123;    scanf(&quot;%d%d%d%d&quot;, &amp;n, &amp;m, &amp;s, &amp;t);    for (int i = 1, ui, vi, wi, fi; i &lt;= m; i++) &#123;        scanf(&quot;%d%d%d%d&quot;, &amp;ui, &amp;vi, &amp;wi, &amp;fi);        ade(ui, vi, wi, fi);        ade(vi, ui, 0, -fi);    &#125;    solve();    printf(&quot;%d %d&quot;, ansf, ansc);    return 0;&#125;
最大流
忘写了一些东西 当前弧优化实属op
#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#define MAXN (200)#define MAXM (5000)#define INF (2139062143)#define rev(i) ((((i) - 1) ^ 1) + 1)#define LL long longusing namespace std;struct edg &#123;    int from, to, next, cap, flow;&#125; b[(MAXM &lt;&lt; 1) + 5];int g[MAXN + 5], cntb, n, m, s, t, dis[MAXN + 5], cur[MAXN + 5];LL ans;void ade(int fr, int tr, int ca) &#123;    b[++cntb] = &#123;fr, tr, g[fr], ca, 0&#125;;    g[fr] = cntb;&#125;bool bfs() &#123;    for (int i = 1; i &lt;= n; i++) cur[i] = g[i];    memset(dis, 0, sizeof(dis));    queue&lt;int&gt; q;    q.push(s);    dis[s] = 1;    while (!q.empty()) &#123;        int now = q.front();        q.pop();        for (int i = g[now]; i; i = b[i].next)            if (b[i].cap &gt; b[i].flow &amp;&amp; !dis[b[i].to])                dis[b[i].to] = dis[now] + 1, q.push(b[i].to);    &#125;    return dis[t];&#125;LL dinic(int now, int maxf) &#123;    LL re = 0, zl;    if (now == t || !maxf) return maxf;    for (int i = cur[now]; i; i = b[i].next)        if (b[i].cap &gt; b[i].flow &amp;&amp; dis[b[i].to] == dis[now] + 1) &#123;            cur[now] = i;            zl = dinic(b[i].to, min(maxf, b[i].cap - b[i].flow));            maxf -= zl;             b[i].flow += zl;            b[rev(i)].flow -= zl;            re += zl;        &#125;    return re;&#125;void solve() &#123;    while (bfs())        ans += dinic(s, INF);&#125;int main() &#123;    scanf(&quot;%d%d%d%d&quot;, &amp;n, &amp;m, &amp;s, &amp;t);    for (int i = 1, ui, vi, wi; i &lt;= m; i++) &#123;        scanf(&quot;%d%d%d&quot;, &amp;ui, &amp;vi, &amp;wi);        ade(ui, vi, wi), ade(vi, ui, 0);    &#125;    solve();    printf(&quot;%lld&quot;, ans);    return 0;&#125;
缩点
妈的把i和j搞混了
#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;stack&gt;#define MAXN (10000)#define MAXM (100000)using namespace std;struct edg &#123;    int from, to, next;&#125; b[MAXM + 5], nb[MAXM + 5];int g[MAXN + 5], ng[MAXN + 5], n, m, cntb, ncntb, belong[MAXN + 5], f[MAXN + 5], dfn[MAXN + 5], low[MAXN + 5], cntdfn, a[MAXN + 5],     na[MAXN + 5];bool ins[MAXN + 5];stack&lt;int&gt; gary;void ade(int* dg, edg* db, int&amp;dcntb, int fr, int tr) &#123;    db[++dcntb] = &#123;fr, tr, dg[fr]&#125;;    dg[fr] = dcntb;&#125;void tarjan(int now) &#123;    belong[now] = now;    low[now] = dfn[now] = ++cntdfn;    ins[now] = true;    gary.push(now);    for (int i = g[now]; i; i = b[i].next)        if (ins[b[i].to])            low[now] = min(low[now], dfn[b[i].to]);        else if (!dfn[b[i].to])            tarjan(b[i].to), low[now] = min(low[now], low[b[i].to]);    if (low[now] == dfn[now]) &#123;        while (gary.top() != now) &#123;            ins[gary.top()] = false;            belong[gary.top()] = now;            gary.pop();        &#125;        gary.pop();        ins[now] = false;    &#125;&#125;int dfs(int now) &#123;    if (f[now] &gt;= 0) return f[now];    f[now] = na[now];     for (int i = ng[now]; i; i = nb[i].next)        f[now] = max(f[now], na[now] + dfs(nb[i].to));    return f[now];&#125;void solve() &#123;    for (int i = 1; i &lt;= n; i++)        if (!dfn[i])            tarjan(i);    for (int i = 1; i &lt;= n; i++) &#123;        na[belong[i]] += a[i];        for (int j = g[i]; j; j = b[j].next)            if (belong[b[j].to] != belong[b[j].from])                ade(ng, nb, ncntb, belong[b[j].from], belong[b[j].to]);    &#125;    memset(f, -1, sizeof(f));    for (int i = 1; i &lt;= n; i++)        if (f[belong[i]] == -1)            dfs(belong[i]);    int ans = 0;    for (int i = 1; i &lt;= n; i++)        ans = max(ans, f[belong[i]]);    printf(&quot;%d&quot;, ans);&#125;int main() &#123;    scanf(&quot;%d%d&quot;, &amp;n, &amp;m);    for (int i = 1; i &lt;= n; i++) scanf(&quot;%d&quot;, &amp;a[i]);    for (int i = 1, ui, vi; i &lt;= m; i++) scanf(&quot;%d%d&quot;, &amp;ui, &amp;vi), ade(g, b, cntb, ui, vi);    solve();    return 0;&#125;
