#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;using namespace std;int main() &#123;    int t;    scanf(&quot;%d&quot;, &amp;t);    while (t--) &#123;        int n, ans = 0;        scanf(&quot;%d&quot;, &amp;n);        for (int i = 1, ai; i &lt;= n; i++)            scanf(&quot;%d&quot;, &amp;ai), ans ^= ai;        puts(ans ? &quot;Yes&quot; : &quot;No&quot;);    &#125;    return 0;&#125;
负权多源最短路
这题有点意思
把每条边的边权变为b[i].cost - dis[0][b[i].from] + dis[0][b[i].to]这样以来在求最短路的时候中间部分能全部消掉,
而用Bellman-ford预处理的时候已经保证了dis[0][b[i].from] + cost &gt;= dis[0][b[i].to]](不然就松弛了)
#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#include &lt;vector&gt;#define MAXN (3000)#define MAXM (6000)#define INF (1000000000)#define LL long long#define pii pair&lt;int, int&gt;using namespace std;struct edg &#123;    int from, to, cost, next;&#125; b[MAXM + MAXN + 5];struct cmp &#123;    bool operator () (const pii x, const pii y) &#123; return x.second &gt; y.second; &#125;&#125;;int g[MAXN + 5], cntb, n, m, hdis[MAXN + 5], dis[MAXN + 5];bool vis[MAXN + 5];LL ans;void ade(int fr, int tr, int cr) &#123;    b[++cntb] = &#123;fr, tr, cr, g[fr]&#125;;    g[fr] = cntb;&#125;bool bellmanFord() &#123;    for (int i = 1; i &lt;= n; i++) ade(0, i, 0);    memset(hdis, 0x7f, sizeof(hdis));    hdis[0] = 0;    for (int i = 1; i &lt;= n; i++)        for (int j = 1; j &lt;= cntb; j++)            if (hdis[b[j].from] &lt; INF)                hdis[b[j].to] = min(hdis[b[j].to], hdis[b[j].from] + b[j].cost);    for (int i = 1; i &lt;= cntb; i++)        if (hdis[b[i].to] &gt; hdis[b[i].from] + b[i].cost)            return false;    return true;&#125;void dijk(int s) &#123;    priority_queue&lt;pii, vector&lt;pii&gt;, cmp&gt; q;    memset(vis, false, sizeof(vis));    for (int i = 1; i &lt;= n; i++) dis[i] = INF;    dis[s] = 0;    q.push(make_pair(s, 0));    while (!q.empty()) &#123;        int now = q.top().first;        q.pop();        if (vis[now]) continue;        vis[now] = true;        for (int i = g[now]; i; i = b[i].next)            if (dis[b[i].to] &gt; dis[now] + b[i].cost)                dis[b[i].to] = dis[now] + b[i].cost, q.push(make_pair(b[i].to, dis[b[i].to]));    &#125;    ans = 0;    for (int i = 1; i &lt;= n; i++)        if (dis[i] != INF)            ans += (LL)i * (dis[i] - hdis[s] + hdis[i]);        else            ans += (LL)i * INF;    printf(&quot;%lld\n&quot;, ans);&#125;int main() &#123;    scanf(&quot;%d%d&quot;, &amp;n, &amp;m);    for (int i = 1, ui, vi, ci; i &lt;= m; i++)        scanf(&quot;%d%d%d&quot;, &amp;ui, &amp;vi, &amp;ci), ade(ui, vi, ci);    if (!bellmanFord()) &#123;        puts(&quot;-1&quot;);        return 0;    &#125;    for (int i = 1; i &lt;= cntb; i++)        b[i].cost += hdis[b[i].from], b[i].cost -= hdis[b[i].to];    for (int i = 1; i &lt;= n; i++) dijk(i);    return 0;&#125;
