#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#define MAXN (1000)#define MAXG (200)#define MAXM (200000)#define INF (0x7ffffff)#define nnum(i) ((i) + MAXG)#define rev(i) ((((i) - 1) ^ 1) + 1)using namespace std;struct edg &#123;	int from, to, next, cap, flow, cost;&#125; b[MAXM * 2 + 5];int n, m, g[MAXN + 5], cntb, s = MAXN + 1, t = MAXN + 2, ansf, ansc, pre[MAXN + 5];void ade(int fr, int to, int ca, int co) &#123;	b[++cntb] = &#123;fr, to, g[fr], ca, 0, co&#125;;	g[fr] = cntb;&#125;int spfa() &#123;	int dis[MAXN + 5], a[MAXN + 5];	bool inq[MAXN +5];	memset(dis, 0x7f, sizeof(dis));	memset(a, 0, sizeof(a));	memset(inq, false, sizeof(inq));	queue&lt;int&gt; q;	dis[s] = 0;	a[s] = INF;	q.push(s);	while (!q.empty()) &#123;		int now = q.front();		q.pop();		inq[now] = false;		for (int i = g[now]; i; i = b[i].next)			if (b[i].cap &gt; b[i].flow &amp;&amp; dis[now] + b[i].cost &lt; dis[b[i].to]) &#123;				dis[b[i].to] = dis[now] + b[i].cost;				a[b[i].to] = min(a[now], b[i].cap - b[i].flow);				pre[b[i].to] = i;				if (!inq[b[i].to]) q.push(b[i].to), inq[b[i].to] = true;			&#125;	&#125;	return a[t];&#125;void solve() &#123;	int x;	while (x = spfa()) &#123;		for (int i = t; i != s; i = b[pre[i]].from)			ansc += b[pre[i]].cost, b[pre[i]].flow += x, b[rev(pre[i])].flow -= x;		++ansf;	&#125;&#125;int main() &#123;	scanf(&quot;%d%d&quot;, &amp;n, &amp;m);	for (int i = 1, ai, bi, ci; i &lt;= m; i++) &#123;		scanf(&quot;%d%d%d&quot;, &amp;ai, &amp;bi, &amp;ci);		ade(nnum(ai), bi, 1, ci), ade(bi, nnum(ai), 0, -ci);	&#125;	for (int i = 2; i &lt; n; i++) ade(i, nnum(i), 1, 0), ade(nnum(i), i, 0, 0);	ade(1, nnum(1), INF, 0), ade(nnum(1), 1, 0, 0);	ade(n, nnum(n), INF, 0), ade(nnum(n), n, 0, 0);	ade(s, 1, INF, 0), ade(1, s, 0, 9);	ade(nnum(n), t, INF, 0), ade(t, nnum(n), 0, 0);	solve();	printf(&quot;%d %d&quot;, ansf, ansc);	return 0;&#125;
