#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#define MAXN (200000)#define MAXM (500000)#define INF (0x7ffffff)#define rev(i) ((((i) - 1) ^ 1) + 1)using namespace std;struct edg &#123;	int from, to, next, cap, flow, cost;&#125; b[MAXM + 5];int g[MAXN + 5], cntb, n, m, k, s, t, dis[MAXN + 5], a[MAXN + 5], pre[MAXN + 5], ansc, ansf,	ui[MAXM + 5], vi[MAXM + 5], ci[MAXM + 5], wi[MAXM + 5];bool inq[MAXN + 5];void ade(int fr, int to, int ca, int co) &#123;	b[++cntb] = &#123;fr, to, g[fr], ca, 0, co&#125;;	g[fr] = cntb;&#125;int spfa() &#123;	queue&lt;int&gt; q;	memset(dis, 0x7f, sizeof(dis));	memset(a, 0, sizeof(a));	memset(inq, false, sizeof(inq));	q.push(s);	dis[s] = 0, a[s] = INF;	while (!q.empty()) &#123;		int now = q.front();		q.pop();		inq[now] = false;		for (int i = g[now]; i; i = b[i].next)			if (b[i].cap &gt; b[i].flow &amp;&amp; dis[now] + b[i].cost &lt; dis[b[i].to]) &#123;				dis[b[i].to] = dis[now] + b[i].cost;				pre[b[i].to] = i;				a[b[i].to] = min(a[now], b[i].cap - b[i].flow);				if (!inq[b[i].to]) q.push(b[i].to), inq[b[i].to] = true;			&#125;	&#125;	return a[t];&#125;void solve() &#123;	int x;	while (x = spfa()) &#123;		ansf += x;		for (int i = t; i != s; i = b[pre[i]].from)			b[pre[i]].flow += x, b[rev(pre[i])].flow -= x, ansc += b[pre[i]].cost * x;	&#125;&#125;int main() &#123;	scanf(&quot;%d%d%d&quot;, &amp;n, &amp;m, &amp;k);	s = 1, t = n + 1;	ade(n, t, INF, 0), ade(t, n, 0, 0);	for (int i = 1; i &lt;= m; i++) &#123;		scanf(&quot;%d%d%d%d&quot;, &amp;ui[i], &amp;vi[i], &amp;ci[i], &amp;wi[i]);		ade(ui[i], vi[i], ci[i], 0), ade(vi[i], ui[i], 0, 0);	&#125;	solve();	b[1].cap = ansf + k;	for (int i = 1; i &lt;= m; i++)		ade(ui[i], vi[i], INF, wi[i]), ade(vi[i], ui[i], 0, -wi[i]);	solve();	printf(&quot;%d %d&quot;, ansf - k, ansc);	return 0;&#125;
