#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#define MAXN (400000)#define MAXX (20)#define MAXG (400)#define MAXM (500000)#define INF (0x7ffffff)#define nbh(i, j) (bh(i, j) + MAXG)#define bh(i, j) (((i) - 1) * MAXX + (j))#define rev(i) ((((i) - 1) ^ 1) + 1)using namespace std;struct edg &#123;	int from, to, next, cap, flow;&#125; b[MAXM + 5];int s = MAXN + 1, t = MAXN + 2, n, m, dis[MAXN + 5], kk, hei[MAXG + 5][MAXG + 5], ans, cntb, g[MAXN + 5];bool dist(int x, int y) &#123;	return (x &lt;= kk || y &lt;= kk || n - x &lt; kk || m - y &lt; kk);&#125;void ade(int fr, int to, int ca) &#123;	b[++cntb] = &#123;fr, to, g[fr], ca, 0&#125;;	g[fr] = cntb;&#125;int dinic(int now, int maxf) &#123;	if (now == t || !maxf) return maxf;	int re = 0;	for (int i = g[now]; i; i = b[i].next)		if (b[i].cap &gt; b[i].flow &amp;&amp; dis[b[i].to] == dis[now] + 1) &#123;			int zl = dinic(b[i].to, min(maxf, b[i].cap - b[i].flow));			re += zl;			maxf -= zl;			b[i].flow += zl, b[rev(i)].flow -= zl;		&#125;	return re;&#125;bool bfs() &#123;	queue&lt;int&gt; q;	memset(dis, -1, sizeof(dis));	dis[s] = 0;	q.push(s);	while (!q.empty()) &#123;		int now = q.front();		q.pop();		for (int i = g[now]; i; i = b[i].next)			if (b[i].cap &gt; b[i].flow &amp;&amp; dis[b[i].to] == -1)				dis[b[i].to] = dis[now] + 1, q.push(b[i].to);	&#125;	return (dis[t] != -1);&#125;void solve() &#123;	while (bfs())		ans -= dinic(s, INF);&#125;int main() &#123;	scanf(&quot;%d%d%d&quot;, &amp;n, &amp;m, &amp;kk);	for (int i = 1; i &lt;= n; i++) &#123;		char ss[MAXG + 5];		scanf(&quot;%s&quot;, ss);		for (int j = 1; j &lt;= m; j++)			hei[i][j] = ss[j - 1] - &#x27;0&#x27;;	&#125;	for (int i = 1; i &lt;= n; i++)		for (int j = 1; j &lt;= m; j++)			if (hei[i][j]) &#123;				ade(bh(i, j), nbh(i, j), hei[i][j]), ade(nbh(i, j), bh(i, j), 0);				if (dist(i, j))					ade(nbh(i, j), t, INF), ade(t, nbh(i, j), 0);			&#125;	for (int i = 1; i &lt;= n; i++)		for (int j = 1; j &lt;= m; j++)			for (int ii = 1; ii &lt;= n; ii++)				for (int jj = 1; jj &lt;= m; jj++)					if (abs(i - ii) + abs(j - jj) &lt;= kk &amp;&amp; (ii!= i || jj != j) &amp;&amp; hei[i][j] &amp;&amp; hei[ii][jj])						ade(nbh(i, j), bh(ii, jj), INF), ade(bh(ii, jj), nbh(i, j), 0);	for (int i = 1; i &lt;= n; i++) &#123;		char ss[MAXG + 5];		scanf(&quot;%s&quot;, ss);		for (int j = 1; j &lt;= m; j++)			if (ss[j - 1] == &#x27;L&#x27;)				ade(s, bh(i, j), 1), ade(bh(i, j), s, 0), ++ans;	&#125;	solve();	printf(&quot;%d&quot;, ans);	return 0;&#125;
