f (xi) ade(i, bh(j), 1), ade(bh(j), i, 0);			&#125;		solve();		puts(ans ? &quot;T_T&quot; : &quot;^_^&quot;);	&#125;	return 0;&#125;
方格取数
印象里好像做过, 但是没有系统的学习背后的原理, 导致现在屁都不会
这个东西,
首先我们把棋盘上相交的格子两两连边就发现这玩意其实让求得就是一个二分图带权的最大独立子集
那怎么处理这个权的问题呢,
我们就可以把一个点复制成a[i]个点,
然后按照原先的关系连边跑就可以了
后来我们又发现, 这个边数好像有点爆炸, 怎么办呢,
我们观察一下这张图发现,
我们可以把一个点复制出的a[i]个点再合并起来,
在左部只需要把s到这个点的cap改成a[i],
在右部就把到t的cap改成相应的权值,
然后两部之间的边cap设为INF即可(因为不是限制条件,
当然, 设成两边点权的 \(\max\)
也可以)
然后跑最大流就可以了
不过要注意一个问题, 因为这张二分图的cap不都是1了,
所以连边一定要注意不要从右部连向左部的多余的边, 否则会出现
左部-&gt;右部-&gt;左部-&gt;右部 的奇妙路径
#include &lt;iostream&gt;#include &lt;cstdio&gt;#include &lt;cstring&gt;#include &lt;cstdlib&gt;#include &lt;algorithm&gt;#include &lt;queue&gt;#define MAXN 100000#define MAXM 500000#define INF 100000#define bh(i, j) (((i) - 1) * 1000 + (j))#define rev(i) ((((i) - 1) ^ 1) + 1)using namespace std;const int xy[4][2] = &#123;&#123;1, 0&#125;, &#123;0, 1&#125;, &#123;-1, 0&#125;, &#123;0, -1&#125;&#125;;struct edg &#123;	int from, to, next, flow, cap;&#125; b[MAXM * 2 + 5];int g[MAXN + 5], cntb, n, dis[MAXN + 5], s = MAXN + 1, t = MAXN + 2, ans;void ade(int fr, int to, int ca) &#123;	b[++cntb] = &#123;fr, to, g[fr], 0, ca&#125;;	g[fr] = cntb;&#125;bool bfs() &#123;	queue&lt;int&gt; q;	memset(dis, -1, sizeof(dis));	q.push(s), dis[s] = 0;	while (!q.empty()) &#123;		int now = q.front();		q.pop();		for (int i = g[now]; i; i = b[i].next)			if (b[i].cap &gt; b[i].flow &amp;&amp; dis[b[i].to] == -1)				dis[b[i].to] = dis[now] + 1, q.push(b[i].to);	&#125;	return dis[t] != -1;&#125;int dinic(int now, int maxf) &#123;	if (now == t || !maxf) return maxf;	int re = 0;	for (int i = g[now]; i; i = b[i].next)		if (b[i].cap &gt; b[i].flow &amp;&amp; dis[b[i].to] == dis[now] + 1) &#123;			int zl = dinic(b[i].to, min(maxf, b[i].cap - b[i].flow));			re += zl, maxf -= zl;			b[i].flow += zl, b[rev(i)].flow -= zl;		&#125;	return re;&#125;void solve() &#123;	while (bfs()) ans -= dinic(s, INF * 1000);&#125;int main() &#123;	scanf(&quot;%d&quot;, &amp;n);	for (int i = 1; i &lt;= n; i++)		for (int j = 1, aij; j &lt;= n; j++) &#123;			scanf(&quot;%d&quot;, &amp;aij);			if ((i + j) &amp; 1) ade(bh(i, j), t, aij), ade(t, bh(i, j), 0);			else &#123;				ade(s, bh(i, j), aij), ade(bh(i, j), s, 0);				// 注意这里连边一定要单向连边, 因为cap很大, 所以可能从左部流到右部再流到左部再流到右部...				for (int k = 0; k &lt; 4; k++) &#123; 										int ni = i + xy[k][0], nj = j + xy[k][1];					if (ni &lt; 1 || nj &lt; 1 || ni &gt; n || nj &gt; n) continue;					ade(bh(i, j), bh(ni, nj), INF);					ade(bh(ni, nj), bh(i, j), 0);				&#125;			&#125;			ans += aij;		&#125;	solve();	printf(&quot;%d&quot;, ans);	return 0;&#125;
